mapper.update:
UPDATE task_run
SET device_id = COALESCE(device_id, #{deviceId}),
    lease_expires_at = #{leaseExpiresAt},
    last_heartbeat_at = #{lastHeartbeatAt}
WHERE id = #{id}

UPDATE task_run
SET last_event_at = CASE
        WHEN last_event_at IS NULL OR last_event_at < #{lastEventAt}
        THEN #{lastEventAt}
        ELSE last_event_at
    END
WHERE id = #{id}
